"""Camera-calibrated joint controller for this single real-robot-style episode.
All geometry feedback comes from RGB/depth and supplied camera calibration.
No simulator model or object state is used.
"""
import os, sys, json, time, argparse
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.linalg import expm, logm
from scipy.optimize import least_squares
from PIL import Image, ImageDraw
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot
ROOT='/app/runs'
CAMS=['overhead_cam','teleoperator_pov','wrist_cam_left','wrist_cam_right']

def skew(v):
 x,y,z=v;return np.array([[0,-z,y],[z,0,-x],[-y,x,0]])
def hat(s):
 a=np.zeros((4,4));a[:3,:3]=skew(s[:3]);a[:3,3]=s[3:];return a

def pose(o,arm):return np.array(o.meta['cameras']['wrist_cam_'+arm]['cam2world_gl'])
def qpos(o):return np.array(o.meta['proprio']['now'][:14])
def targets(o):return np.array(o.meta['proprio']['now'][28:42])
def save(o,name):
 p=f'{ROOT}/{name}';o.save(p)
 np.savez(p+'/arrays.npz',**{f'rgb_{k}':v for k,v in o.last.items()},**{f'depth_{k}':v for k,v in o.depth.items()})
 out=Image.new('RGB',(1280,1000));d=ImageDraw.Draw(out)
 for i,n in enumerate(CAMS):
  if n in o.last:
   out.paste(Image.fromarray(o.last[n]).resize((640,480)),((i%2)*640,(i//2)*500));d.text(((i%2)*640,(i//2)*500+480),n)
 out.save(p+'/views.png');print('SAVED',p,'q',qpos(o).round(5).tolist(),'remaining',o.meta.get('time_left_s'),flush=True)
 return o

def observe(r,name):return save(r.get_obs(cameras=CAMS,include_depth=True),name)
def move(r,q,name,secs=2.,hold=1.):
 o=r.submit('joint_position',np.array(q)[None,:],dt=secs,cameras=CAMS,include_depth=True,video='frames',note=name)
 if hold:o=r.get_obs(cameras=CAMS,include_depth=True,seconds=hold)
 return save(o,name)

def cloud(o,cam,color):
 im=o.last[cam].astype(float);D=o.depth[cam].astype(float).squeeze();C=o.meta['cameras'][cam];K=np.array(C['intrinsic_cv']);T=np.array(C['cam2world_gl'])
 if color=='blue':m=(im[:,:,2]>1.8*im[:,:,0])&(im[:,:,2]>1.5*im[:,:,1])&(im[:,:,2]>65)
 elif color=='red':m=(im[:,:,0]>1.8*im[:,:,1])&(im[:,:,0]>1.8*im[:,:,2])&(im[:,:,0]>80)
 else:m=color
 y,x=np.where(m);z=D[y,x];P=np.stack([(x-K[0,2])*z/K[0,0],-(y-K[1,2])*z/K[1,1],-z],1)@T[:3,:3].T+T[:3,3]
 return P,np.stack([x,y],1)

def loadobs(name):
 from types import SimpleNamespace
 p=f'{ROOT}/{name}';d=np.load(p+'/arrays.npz');return SimpleNamespace(meta=json.load(open(p+'/meta.json')),last={c:d['rgb_'+c] for c in CAMS if 'rgb_'+c in d},depth={c:d['depth_'+c] for c in CAMS if 'depth_'+c in d})

class Kinematics:
 def __init__(self,arm):
  d=np.load(f'{ROOT}/kin_{arm}.npz');self.S=d['S'];self.q0=d['q0'];self.T0=d['T0'];self.arm=arm;self.offset=np.array([0.,0.,0.])
 def fk(self,q):
  T=np.eye(4)
  for s,a in zip(self.S,q[:6]-self.q0):T=T@expm(hat(s)*a)
  return T@self.T0
 def ik(self,T,q):
  def error(a):
   X=self.fk(a);return np.r_[(X[:3,3]-T[:3,3])*5,Rotation.from_matrix(T[:3,:3].T@X[:3,:3]).as_rotvec(),.005*(a-q[:6])]
  spec=Robot().spec()['action_types']['joint_position'];i=0 if self.arm=='left' else 7
  res=least_squares(error,q[:6],bounds=(np.array(spec['lower'][i:i+6])+.0001,np.array(spec['upper'][i:i+6])-.0001),xtol=1e-11,ftol=1e-11,gtol=1e-11,max_nfev=300)
