   es.extend(np.sum(ss[:,:3]*ss[:,3:],axis=1)*.2)
   return es
  res=least_squares(error,S.ravel(),max_nfev=100,xtol=1e-10,gtol=1e-10,ftol=1e-10);S=res.x.reshape(6,6)
  print(arm,'error',np.linalg.norm(error(res.x)), 'S',S)
  np.savez(f'{ROOT}/kin_{arm}.npz',S=S,q0=q0,T0=T0)

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('cmd');p.add_argument('--q',nargs=14,type=float);p.add_argument('--name',default='obs');p.add_argument('--secs',type=float,default=2.);a=p.parse_args()
 if a.cmd=='identify':identify()
 elif a.cmd=='fit':fit_kinematics()
 elif a.cmd=='obs':observe(Robot(),a.name)
 elif a.cmd=='move':move(Robot(),a.q,a.name,a.secs)
